#define FOV 		60.0


float flexTime(){
    return 4.0*(iTime+2.0*sin(iTime*.5));
}

float sdSphere( vec3 p, float s )
{
  return length(p)-s;
}

float opSubtraction( float d1, float d2 )
{
    return max(-d1,d2);
}


float soap_bubbles( vec3 p,int lastType){
    float m=100000.;
    float wall = 0.001;
    for(int i=0; i<bubbleCount; i++){
        vec4 drop = texture(iChannel2,vec2(float(i)+0.25,0.25)/iResolution.xy);
        vec3 q = p-drop.xyz;
        //m=min(m, max(-(length(drop.xyz)-(drop.w-0.03)),length(drop.xyz)-(drop.w)));
        //m=min(m,opSubtraction(sdSphere(q,drop.w-wall),sdSphere(q,drop.w)));
        if(lastType==1){
            float soap =sdSphere(q,drop.w);
            m=min(m,soap);
        }else if(lastType==2){
            float soap =sdSphere(q,-drop.w);
            m=min(m,soap);
        }

    }
    return m;
}


vec4 skyColor(in vec3 ro, in vec3 rd){
    return texture(iChannel0, normalize(rd));
}

vec4 bubbleColor(in vec3 ro, in vec3 rd){
    return texture(iChannel1, flexTime()*0.003+0.03*(rd.zx+rd.yz+rd.yx));
}


vec2 map_the_world(in vec3 p, int lastType){
    return vec2(2,soap_bubbles(p, lastType));
}


vec3 calculate_normal(in vec3 p,int lastType){
    const vec3 small_step = vec3(0.00001, 0.0, 0.0);
    float gradient_x = map_the_world(p + small_step.xyy, lastType).y - map_the_world(p - small_step.xyy, lastType).y;
    float gradient_y = map_the_world(p + small_step.yxy, lastType).y - map_the_world(p - small_step.yxy, lastType).y;
    float gradient_z = map_the_world(p + small_step.yyx, lastType).y - map_the_world(p - small_step.yyx, lastType).y;
    vec3 normal = vec3(gradient_x, gradient_y, gradient_z);
    return normalize(normal);
}


vec4 ray_march(in vec3 ro, in vec3 rd){
    const int NUMBER_OF_STEPS = 32;
    int lastType = 1;
    int lastType_reflected = 1;
    const float MINIMUM_HIT_DISTANCE = 0.001;
    const float MAXIMUM_TRACE_DISTANCE = 14.0;
    float watereffect = 0.;
    vec3 light_position = vec3(0,1,0);
    vec3 ro_reflected = vec3(0);
    vec3 rd_reflected = vec3(0);
    float reflection_multiplier = 0.0;
    vec3 current_position_reflected = vec3(0);
    vec3 current_position = ro;
    float total_distance_traveled = 0.;
    for (int i = 0; i < NUMBER_OF_STEPS; ++i)
    {
        vec2 distance_to_closest = map_the_world(current_position,lastType);
        current_position += rd*distance_to_closest.y;
        total_distance_traveled+=distance_to_closest.y;
        if(ro_reflected != vec3(0)){
            vec2 distance_to_closest_reflected = map_the_world(current_position_reflected,lastType);
            current_position_reflected += rd_reflected*distance_to_closest_reflected.y;
            if (abs(distance_to_closest_reflected.y) <= MINIMUM_HIT_DISTANCE ) 
            {
                float fIn = 1.4;
                float fOut= 1.0;
                if(lastType_reflected ==2){
                    fIn =1.0;
                    fOut = 1.4;
                }
                vec3 normal_reflected = calculate_normal(current_position_reflected,lastType);
                ro_reflected=current_position_reflected;
                rd_reflected = normalize((fOut/fIn)*(cross(normal_reflected,cross(-normal_reflected,rd_reflected))-normal_reflected*sqrt(fOut-pow(fOut/fIn,2.0)*dot(cross(normal_reflected,rd_reflected),cross(normal_reflected,rd_reflected)))));

                lastType_reflected = lastType_reflected==1?2:1;
            }
        }else if (distance_to_closest.y < MINIMUM_HIT_DISTANCE) {

            vec3 normal = calculate_normal(current_position, lastType);    
            rd_reflected =normalize(reflect(rd, normal));
            ro_reflected = current_position;
            float ref = abs(dot(normalize(rd),cross(light_position,normal)));
            reflection_multiplier = ref;

        }
        if (distance_to_closest.y < MINIMUM_HIT_DISTANCE) 
        {

            vec3 normal = calculate_normal(current_position, lastType);
            ro=current_position;
            float fIn = 1.4;
            float fOut= 1.0;
            if(lastType ==2){
                fIn =1.0;
                fOut = 1.4;
            }
            rd = normalize((fOut/fIn)*(cross(normal,cross(-normal,rd))-normal*sqrt(fOut-pow(fOut/fIn,2.0)*dot(cross(normal,rd),cross(normal,rd)))));
            lastType = lastType==1?2:1;
            //rd = normalize((1.4/1.)*(cross(normal,cross(-normal,rd))-normal*sqrt(1.4-pow(1.4/1.,2.0)*dot(cross(normal,rd),cross(normal,rd)))));
        }
        if (total_distance_traveled > MAXIMUM_TRACE_DISTANCE )
        {
            break;
        } 
    }
    return mix((1.0-reflection_multiplier)*skyColor(ro,rd)+reflection_multiplier*2.*bubbleColor(ro_reflected,rd_reflected)*((ro_reflected!=vec3(0))?vec4(skyColor(ro_reflected,rd_reflected).xyz,0.0):vec4(0)),vec4(0.0,0.0,0.1,1.0),watereffect);
}

vec4 samplePixel(in vec2 fragCoord){
    vec2 uv = (2.*(fragCoord.xy)/iResolution.y-1.) * tan (radians (FOV)/2.0);
	vec3 up = vec3 (0.0, 1.0, 0.0);			// up 
    vec3 fw = vec3 (0, 0.0, -1);			// forward
	vec3 lf = cross (up, fw); 					// left
	vec3 ro = vec3(0); // ray origin
	vec3 rd = normalize (uv.x * lf + uv.y * up + fw) ; 		// ray direction
    vec4 march = ray_march(ro,rd);
    return vec4(march.xyz,1.0);
}

vec4 superSamplePixel(in vec2 fragCoord){
    vec2 step = vec2(.5);
    vec4 sum=vec4(0);
    for(int i=0;i<2;i++){
        for(int j=0; j<2;j++){
            sum+=samplePixel(fragCoord+vec2(i,j)*step);
        }
    }
    return sum*0.25;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    fragColor = samplePixel(fragCoord);
}

