// borrowed IQs hash
  const uint k = 1103515245U;  // GLIB C
//const uint k = 134775813U;   // Delphi and Turbo Pascal
//const uint k = 20170906U;    // Today's date (use three days ago's dateif you want a prime)
//const uint k = 1664525U;     // Numerical Recipes

vec3 hash33( uvec3 x )
{
    x = ((x>>8U)^x.yzx)*k;
    x = ((x>>8U)^x.yzx)*k;
    x = ((x>>8U)^x.yzx)*k;

    return vec3(x)*(1.0/float(0xffffffffU));
}

bool collide(vec4 bubblea, vec4 bubbleb){
    vec3 diff = bubbleb.xyz-bubblea.xyz;
    float len = length(diff);
    return len< bubblea.w+bubbleb.w;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    if(fragCoord.x<float(bubbleCount+1) && fragCoord.y<2.0){
        if(iFrame == 0){
            if( fragCoord.y<1.0){
                fragColor =vec4(6,0,9,0)+vec4(hash33(uvec3(int(iTime*79351.)+113,int(fragCoord.x*iResolution.x)+1773,111))*vec3(7,2,7),0.02+hash33(uvec3(int(iTime*19343.),int(iTime*343.),int(fragCoord.x))).x);
            }else if (fragCoord.y<2.0){
                fragColor = vec4(0);
            }
        }
        else{
            vec4 bubblea = texture(iChannel0,vec2(fragCoord.x+0.25,0.25)/iResolution.xy);
            vec4 speedChange = 0.003*(vec4(-0.5,-0.5,-0.5,0)+vec4(hash33(uvec3(iFrame+113,int(fragCoord.x*iResolution.x)+1773,111)),0.));
            vec4 speed =  speedChange+texture(iChannel0,vec2(fragCoord.x+0.25,1.25)/iResolution.xy);
            vec4 speeddiff =  texture(iChannel0,vec2(fragCoord.x+0.25,2.25)/iResolution.xy);

            //vec4 speeddiff=vec4(0);
            for(int i=0; i<bubbleCount; i++){
                vec4 bubbleb = texture(iChannel0,vec2(float(i)+0.25,0.25)/iResolution.xy);
                if(i!=int(fragCoord.x) &&collide(bubblea,bubbleb)){
                      float massa = 4. * PI * bubblea.w*bubblea.w;
                      float massb = 4. * PI * bubbleb.w*bubbleb.w;
                      float ra = bubblea.w;
                      float rb = bubbleb.w;
                      float desiredDistance = sqrt(
                        ra * ra + rb * rb - 2. * ra * rb * cos(PI / 3.)
                      );
                      float dist = length(bubbleb.xyz-bubblea.xyz);
                      float change = (desiredDistance - dist);
                      float changea = (change * massb) / (massa + massb);
                      float changeb = (change * massa) / (massa + massb);
                      vec3 direction =normalize(bubblea.xyz-bubbleb.xyz);
                      vec3 gravityDiff = bubbleb.xyz-vec3(0,(ra<rb?1.:-1.)*desiredDistance,0)-bubblea.xyz;
                      float gravityChange= length(gravityDiff)*massb/(massa+massb);
                      vec3 gravityDirection= normalize(gravityDiff);
                      speeddiff.xyz +=gravityDirection*gravityChange*0.02;
                      speeddiff.xyz += direction*changea*0.1;
                }
            }
            speed*=0.98; // friction
            speeddiff*=0.98;
            if(iFrame%16 == 0 && (iFrame/16)%bubbleCount == int(fragCoord.x)){
                vec3 r = hash33(uvec3(int(iTime*77351.)+321,int((fragCoord.x+float(bubbleCount))*iResolution.x)+1771,113));
                vec3 r2 = hash33(uvec3(int(iTime*77351.)+321,int(fragCoord.x*iResolution.x)+1771,113));
                bubblea =vec4(-7.5+5.*r.x,-7.+5.*r.y,r.z*4.-12.,r.z+r.x*0.1+0.02);//+vec4(hash33(uvec3(int(iTime*79351.)+113,int(fragCoord.x*iResolution.x)+1773,111))*vec3(7,2,7),0.02+hash33(uvec3(int(iTime*19343.),int(iTime*343.),int(fragCoord.x))).x);
                speed = vec4(r2.y*0.07,0.07+r2.x*0.07,r2.z*0.07,0);//0000001*uBubblesStartSpeed[int(fragCoord.x)];
                speeddiff = vec4(0);
            }
            if( fragCoord.y<1.0){
                fragColor = bubblea + speed+ vec4(speeddiff.xyz,0);
            }else if (fragCoord.y<2.0){
                fragColor = speed;
            }else if (fragCoord.y<3.0){
                fragColor = vec4(speeddiff.xyz,0);
            }
        }
    }else{
        fragColor = vec4(0.0,0.0,0.0,1.0);
    }
}
